class AssessmentSystem:
    FAILING_SCORE_THRESHOLD = 60

    def __init__(self):
        self._students = {}

    def get_students(self):
        return dict(self._students)

    def set_students(self, students):
        self._students = dict(students)

    @property
    def students(self):
        return self.get_students()

    @students.setter
    def students(self, value):
        self.set_students(value)

    def add_student(self, name, grade, major):
        self._students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if name in self._students:
            self._students[name]['courses'][course] = score

    def get_gpa(self, name):
        if not self._has_valid_student_with_courses(name):
            return None
        return self._calculate_gpa(name)

    def _has_valid_student_with_courses(self, name):
        return name in self._students and self._students[name]['courses']

    def _calculate_gpa(self, name):
        courses = self._students[name]['courses']
        return sum(courses.values()) / len(courses)

    def get_all_students_with_fail_course(self):
        return [
            name for name, student in self._students.items()
            if self._has_failing_course(student)
        ]

    def _has_failing_course(self, student):
        return any(score < self.FAILING_SCORE_THRESHOLD for score in student['courses'].values())

    def get_course_average(self, course):
        scores = self._get_course_scores(course)
        if not scores:
            return None
        return sum(scores) / len(scores)

    def _get_course_scores(self, course):
        return [
            student['courses'][course]
            for student in self._students.values()
            if course in student['courses'] and student['courses'][course] is not None
        ]

    def get_top_student(self):
        top_student = None
        top_gpa = 0
        for name, student in self._students.items():
            gpa = self.get_gpa(name)
            if gpa is not None and gpa > top_gpa:
                top_gpa = gpa
                top_student = name
        return top_student
